mapper.update:
UPDATE cinesquare
SET views = views + 1
WHERE post_id = ${postId}

mapper.select:
SELECT cs.post_id AS postId, cs.category_id AS categoryId, c.category_name AS categoryName, cs.title AS title, cs.content AS content, cs.views AS views, cs.created_at AS createdAt, cs.author_id AS authorId, cs.city AS city, cs.district AS district FROM cinesquare cs JOIN category c ON cs.category_id = c.category_id
cs.category_id = #{categoryId}
AND cs.post_id < #{lastPostId}
ORDER BY ${orderBy} LIMIT #{limit}

mapper.update:
UPDATE cinesquare
SET title = #{title}, content = #{content}
WHERE post_id = #{postId} AND author_id = #{authorId}

mapper.select:
SELECT COUNT(*)
FROM post_like_cinesquare
WHERE post_id = #{postId}
AND post_like_user_id = #{userId}

mapper.delete:
DELETE FROM post_like_cinesquare
WHERE post_id = #{postId}
AND post_like_user_id = #{userId}

mapper.update:
UPDATE cinesquare
SET like_count = like_count + 1
WHERE post_id = #{postId}
